CREATE OR REPLACE SNOWFLAKE.ML.FORECAST SDP_JIMDO_TEASER.ML.RETENTION_MODEL(
  INPUT_DATA => TABLE(SDP_JIMDO_TEASER.PUBLIC.V_RETENTION_HISTORY), SERIES_COLNAME => 'SERIES',
  TIMESTAMP_COLNAME => 'PERIOD', TARGET_COLNAME => 'RETENTION');

SELECT AI_COMPLETE('claude-sonnet-4-5',
  'Write FP&A commentary using ONLY these figures: ' || OBJECT_CONSTRUCT(*)::STRING)
FROM SDP_JIMDO_TEASER.SNOWBOTS.BRIDGE_RESULT_TOP5;

SELECT item_code, AI_CLASSIFY(item_name || ' ' || sample_orders,
  (SELECT ARRAY_AGG(label) FROM SDP_JIMDO_TEASER.PUBLIC.DIM_ACCOUNT WHERE is_leaf)) AS mapping
FROM SDP_JIMDO_TEASER.PUBLIC.V_UNMAPPED_ITEMS;

SELECT feed, SNOWFLAKE.CORE.ROW_COUNT(...) AS rows_loaded, expected_rows,
       rows_loaded / expected_rows AS completeness
FROM SDP_JIMDO_TEASER.SNOWBOTS.V_FEED_EXPECTATIONS WHERE period = '2026-10';

